import assert from 'node:assert/strict';
import { test } from 'node:test';
import { NAMES } from '../src/registry.js';

test('the registry starts with core', () => {
  assert.equal(NAMES[0], 'core');
});

test('urgent is registered (A2)', () => {
  assert.ok(NAMES.includes('urgent'));
});
